import React, { useRef, useState, useEffect } from 'react'
import { View, Text, Animated, Dimensions, TouchableOpacity, Button, StyleSheet } from 'react-native'

import { useContexState } from '../../../hooks/context';


export function Alert() {
    const fadeAnim = useRef(new Animated.Value(0)).current;
    const [active, setActive] = useState(false);
    const { alertMessage, setAlertMessage } = useContexState()

    function fade(value: number, message = '') {
        setActive(true);
        Animated.timing(fadeAnim, {
            toValue: value,
            duration: 1000,
        } as Animated.TimingAnimationConfig).start(() => {
            if (value === 0) {
                setActive(false)
            };
        });
        console.log('123123sfsdf')
    };


    useEffect(() => {
        fade(alertMessage.active, alertMessage.message)
    }, [alertMessage])


    function AlertTSX() {
        return <>
            <Button onPress={() => fade(1, 'O número já está no carrinho!')} title='Button' />
            {active ? <>
                <TouchableOpacity
                    onPress={() => { setAlertMessage({ ...alertMessage, active: 0 }) }}
                    style={{
                        position: 'absolute',
                        alignItems: 'center',
                        justifyContent: 'center',
                        minWidth: Dimensions.get('window').width,
                        minHeight: Dimensions.get('window').height
                    }} />

                <Animated.View style={[styles.container, { opacity: fadeAnim }]} >
                    <Text style={styles.listText}>{alertMessage}</Text>
                </Animated.View>
            </> : null}
        </>
    }


    //transform: [{ scale: fadeAnim }]
    return { AlertTSX }
};




const styles = StyleSheet.create({
    container: {
        alignItems: 'center',
        position: 'absolute',
        backgroundColor: 'rgba(0,0,0,0.8)',
        borderRadius: 20,
        borderWidth: 3,
        borderColor: '#356',
        justifyContent: 'space-around',
    },

    listText: {
        color: '#fff',
        fontSize: 30,
        textAlign: 'center',
        marginHorizontal: 10,
        paddingVertical: 20,
    },

});





